CREATE INDEX IF NOT EXISTS idx_escalations_order_id ON public.escalations(order_id);
CREATE INDEX IF NOT EXISTS idx_farmers_region_slug ON public.farmers(region_slug);
CREATE INDEX IF NOT EXISTS idx_notify_requests_farmer_id ON public.notify_requests(farmer_id);
CREATE INDEX IF NOT EXISTS idx_price_guidelines_updated_by ON public.price_guidelines(updated_by);
CREATE INDEX IF NOT EXISTS idx_produce_listings_farmer_id ON public.produce_listings(farmer_id);
CREATE INDEX IF NOT EXISTS idx_reviews_produce_listing_id ON public.reviews(produce_listing_id);

-- orders: identical duplicate policies, keep the public_* naming convention
DROP POLICY IF EXISTS "authenticated insert orders" ON public.orders;
DROP POLICY IF EXISTS "public read orders" ON public.orders;

-- reviews: "public_select_reviews" (qual: true) was silently overriding the
-- approved=true restriction on "Public read reviews" since permissive
-- policies are OR'd. Dropping it restores the intended restriction.
DROP POLICY IF EXISTS "public_select_reviews" ON public.reviews;

-- wa_clicks: "anon" role is a subset of "public", so the anon-scoped policy
-- is fully redundant with the public one.
DROP POLICY IF EXISTS "anon insert wa_clicks" ON public.wa_clicks;

